model.component("comp1").physics().create("gb", "GeneralFormBoundaryPDE", "geom1");
model.component("comp1").physics("gb").selection().set(3);
// set Ga to -D(u)*(tangential gradient) and f to the surface reaction in the General Form PDE node

model.component("comp1").physics("c").create("cons1", "Constraint", 2);
model.component("comp1").physics("c").feature("cons1").selection().set(6);
model.component("comp1").physics("c").feature("cons1").set("R", "u - v");  // couple two variables on a boundary

model.component("comp1").physics("c").create("disc1", "Discretization", -1);
model.component("comp1").physics("c").feature("disc1").set("shapeorder", "1");
// Study 2 > Stationary > Physics and Variables Selection: Discretization = disc1

model.component("comp1").common().create("pnmv1", "PrescribedNormalMeshVelocity");
model.component("comp1").common("pnmv1").selection().set(4);
// normal velocity = -etch_rate from a Charged Particle Tracing Etch subnode or a reaction rate
